+// API keys, role checks and the audit log of data-changing requests.
+import { AppError } from "../errors.js";
+
+/** Supported API key roles. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+const COOK_WRITES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key record for a bearer token, or throws unauthorized. */
+export function authenticate(store, token) {
+  if (typeof token !== "string" || !token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks whether `apiKey` may call `method` on `pathname`, or throws forbidden. */
+export function authorize(apiKey, method, pathname) {
+  const role = apiKey?.role;
+  if (role === "manager") return;
+  if (role === "viewer") {
+    if (method === "GET" && pathname !== "/audit") return;
+    throw new AppError("forbidden");
+  }
+  if (role === "cook") {
+    if (method === "GET" && pathname !== "/audit") return;
+    if (method === "POST" && COOK_WRITES.some((re) => re.test(pathname))) return;
+    throw new AppError("forbidden");
+  }
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Every audit entry, newest first. */
+export function listAudit(store) {
+  return (store.data.audit ?? [])
+    .map((entry, idx) => ({ entry, idx }))
+    .sort((a, b) => b.entry.at.localeCompare(a.entry.at) || b.idx - a.idx)
+    .map(({ entry }) => entry);
+}
