@@ -0,0 +1,152 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { copyFileSync, mkdtempSync, readFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { openStore } from "../src/db/store.js";
+import { CODES } from "../src/errors.js";
+import { messageKeys, t } from "../src/i18n/messages.js";
+import { createApp } from "../src/http/server.js";
+import { app, authHeader, fresh, NOW, seed } from "./helpers.js";
+
+test("seed has one API key per role", () => {
+  const keys = seed().apiKeys;
+  assert.equal(Array.isArray(keys), true);
+  assert.deepEqual(
+    keys.map((k) => k.role).sort(),
+    ["cook", "manager", "viewer"],
+  );
+  for (const k of keys) {
+    assert.equal(typeof k.key, "string");
+    assert.ok(k.key.length > 0);
+    assert.equal(typeof k.name, "string");
+    assert.ok(k.name.length > 0);
+  }
+});
+
+test("missing or unknown keys get 401 and forbidden roles get 403 with distinct codes", async () => {
+  const { handle } = app();
+  const noKey = await handle({ path: "/items" });
+  assert.equal(noKey.status, 401);
+  assert.equal(noKey.body.error.code, "unauthorized");
+
+  const badScheme = await handle({ path: "/items", headers: { Authorization: "Basic abc" } });
+  assert.equal(badScheme.status, 401);
+  assert.equal(badScheme.body.error.code, "unauthorized");
+
+  const unknown = await handle({ path: "/items", headers: { Authorization: "Bearer no-such-key" } });
+  assert.equal(unknown.status, 401);
+  assert.equal(unknown.body.error.code, "unauthorized");
+
+  const forbidden = await handle({
+    method: "POST",
+    path: "/orders",
+    headers: authHeader("viewer"),
+    body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] },
+  });
+  assert.equal(forbidden.status, 403);
+  assert.equal(forbidden.body.error.code, "forbidden");
+  assert.notEqual(unknown.body.error.code, forbidden.body.error.code);
+
+  const enKeys = new Set(messageKeys("en"));
+  for (const code of Object.keys(CODES)) assert.equal(enKeys.has(code), true);
+  assert.ok(t("unauthorized", "ko").length > 0);
+  assert.ok(t("forbidden", "ko").length > 0);
+});
+
+test("viewer may only read non-audit GET routes", async () => {
+  const { handle } = app();
+  const viewer = authHeader("viewer");
+
+  assert.equal((await handle({ path: "/items", headers: viewer })).status, 200);
+  assert.equal((await handle({ path: "/batches", headers: viewer })).status, 200);
+  assert.equal((await handle({ path: "/nope", headers: viewer })).status, 404);
+  assert.equal((await handle({ path: "/audit", headers: viewer })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: viewer, body: { portions: 4 } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: viewer, body: { qty: 1 } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: viewer, body: { location: "fridge", celsius: 3 } })).status, 403);
+});
+
+test("cook may read and perform kitchen actions, but not manager actions", async () => {
+  const { handle } = app();
+  const cook = authHeader("cook");
+  const manager = authHeader("manager");
+
+  assert.equal((await handle({ path: "/items", headers: cook })).status, 200);
+  assert.equal((await handle({ path: "/audit", headers: cook })).status, 403);
+
+  // Start stock-take requires manager; entering counts allows cook; finishing requires manager.
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: cook, body: { location: "dry" } })).status, 403);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+  assert.equal(
+    (await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status,
+    200,
+  );
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: cook })).status, 403);
+
+  // Cook recipes, record waste, log temperatures.
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5, reason: "trim" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 4 } })).status, 201);
+
+  // Other writes are manager-only.
+  assert.equal((await handle({ method: "POST", path: "/orders", headers: cook, body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", headers: cook, body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/jobs/nightly", headers: cook })).status, 403);
+});
+
+test("audit entries record data-changing requests and GET /audit returns newest first for managers", async () => {
+  const store = fresh();
+  let tick = NOW;
+  const handle = createApp(store, { clock: () => (tick += 1000) });
+  const cookKey = seed().apiKeys.find((k) => k.role === "cook");
+  const managerKey = seed().apiKeys.find((k) => k.role === "manager");
+  const cook = { Authorization: `Bearer ${cookKey.key}` };
+  const manager = { Authorization: `Bearer ${managerKey.key}` };
+
+  // Reads and failed requests do not write audit entries.
+  await handle({ path: "/items", headers: cook });
+  await handle({ path: "/items" });
+  await handle({ method: "POST", path: "/orders", headers: cook, body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: cook, body: { portions: 999 } });
+  assert.deepEqual((await handle({ path: "/audit", headers: manager })).body, []);
+
+  // Data-changing requests write audit entries.
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 4 } });
+  await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5, reason: "drop" } });
+  await handle({ method: "PUT", path: "/items/1/allergens", headers: manager, body: { allergens: ["celery"] } });
+
+  const res = await handle({ path: "/audit", headers: manager });
+  assert.equal(res.status, 200);
+  assert.equal(res.body.length, 3);
+  assert.deepEqual(
+    res.body.map((e) => ({ keyName: e.keyName, method: e.method, path: e.path, status: e.status })),
+    [
+      { keyName: managerKey.name, method: "PUT", path: "/items/1/allergens", status: 200 },
+      { keyName: cookKey.name, method: "POST", path: "/batches/1/waste", status: 201 },
+      { keyName: cookKey.name, method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.ok(res.body[0].at > res.body[1].at);
+  assert.ok(res.body[1].at > res.body[2].at);
+});
+
+test("audit entries keep newest-first order at equal timestamps and persist to disk", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-audit-"));
+  const file = join(dir, "db.json");
+  copyFileSync(new URL("../data/seed.json", import.meta.url), file);
+  const store = openStore(file);
+  const handle = createApp(store, { clock: () => NOW });
+  const manager = authHeader("manager");
+
+  await handle({ method: "POST", path: "/temperatures", headers: manager, body: { location: "fridge", celsius: 3 } });
+  await handle({ method: "PUT", path: "/items/1/allergens", headers: manager, body: { allergens: ["celery"] } });
+
+  const audit = (await handle({ path: "/audit", headers: manager })).body;
+  assert.deepEqual(
+    audit.map((e) => e.path),
+    ["/items/1/allergens", "/temperatures"],
+  );
+  const saved = JSON.parse(readFileSync(file, "utf8"));
+  assert.equal(saved.audit.length, 2);
+});
